/// <summary>
/// Attribute used in Jay's Sons parser, to indicate which contract class is used in a map datamember.
/// </summary>
public class TFMContractClassAttribute extends SysAttribute implements SysExtensionIAttribute
{
    ClassName           className;

}

Method.Source:
public ClassName parmClassName(ClassName _className = className)
{
    className = _className;

    return className;
}
